const ELEMENT_PROP_KEYS = new Set(["theme","accent","value","label","caption","fontWeight","stagger","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  value: "200",
  label: "components",
  caption: "Ready to ship. Copy one in, own every frame.",
  fontWeight: 500,
  stagger: 3,
  fontFamily: "Outfit",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type ZeroStretchElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ZeroStretchBase>;

const ZeroStretchInner = forwardRef<
  HTMLDivElement,
  ZeroStretchElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ZeroStretch>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ZeroStretchBase
          {...(componentProps as unknown as ComponentProps<typeof ZeroStretchBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ZeroStretch = Interactive.withSchema({
  Component: ZeroStretchInner,
  componentName: "<ZeroStretch>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
